B.ap_=s(["calendar","camera","contacts","location","locationAlways","locationWhenInUse","mediaLibrary","microphone","phone","photos","photosAddOnly","reminders","sensors","sms","speech","storage","ignoreBatteryOptimizations","notification","access_media_location","activity_recognition","unknown","bluetooth","manageExternalStorage","systemAlertWindow","requestInstallPackages","appTrackingTransparency","criticalAlerts","accessNotificationPolicy","bluetoothScan","bluetoothAdvertise","bluetoothConnect","nearbyWifiDevices","videos","audio","scheduleExactAlarm","sensorsAlways","calendarWriteOnly","calendarFullAccess","assistant","backgroundRefresh","accessLocalNetwork"],t.s)
B.alk=s(["Gym management, trainers, and staff are strictly NOT responsible for any physical injury, muscle tear, medical incident, or accident occurring on the premises.","Members engage in exercise voluntarily and assume full personal responsibility for their health and physical safety.","If you have any prior medical conditions, heart issues, or surgery history, you must consult your doctor and inform gym trainers prior to working out."],t.s)
B.a74=new A.f1("injury",B.q4,"Physical Injury & Health Disclaimer (Gym Not Liable)",B.alk)
B.aq8=s(["All fees paid for gym membership, registration, personal training, or packages are strictly 100% NON-REFUNDABLE under any circumstances.","Even if a member attends for only one day, or does not attend a single day after payment, no refund or partial refund will be provided.","No fees will be adjusted against other services or transferred to other months."],t.s)
B.a7c=new A.f1("refund",B.kN,"Strict 100% Non-Refundable Policy",B.aq8)
B.aqr=s(["Gym membership is strictly individual and non-transferable.","No other person, friend, relative, or family member can use the membership in your place.","Member replacement or swapping of registered persons is strictly prohibited. Violating this will lead to immediate cancellation of membership."],t.s)
B.a6Z=new A.f1("transfer",B.mW,"Non-Transferable & No Member Replacement",B.aqr)
B.ajm=s(["All members must re-rack dumbbells, weight plates, and bars back to their designated holders after each exercise.","Dropping weights, slamming machines, or negligent handling is strictly forbidden. Any damage caused to gym property will be recovered from the member.","Carrying a workout towel and wearing clean indoor athletic shoes is strictly mandatory. Sandal/slippers/barefoot workouts are strictly barred."],t.s)
B.a6V=new A.f1("equipment",B.bo,"Gym Equipment Care, Hygiene & Etiquette",B.ajm)
B.aql=s(["Members must strictly attend during their registered batch/shift hours. Entry outside your chosen shift is not allowed without management approval.","Check-in via the app or front-desk QR code is mandatory upon entering.","Gym workout floor must be vacated promptly at the end of the shift / closing time."],t.s)
B.a7d=new A.f1("timing",B.mO,"Shift Timings & Attendance Protocol",B.aql)
B.akI=s(["Members must handle all gym equipment, machinery, weights, dumbbells, mirrors, and accessories with utmost care.","If any equipment, machine, mirror, or gym property is broken or damaged due to negligence, dropping weights, or mishandling, the member is 100% financially liable and must pay the full replacement or repair cost.","Gym workout floor access and membership may be immediately suspended until all damage costs are fully settled by the member."],t.s)
B.a73=new A.f1("damage",B.kK,"Gym Property & Equipment Damage Liability (100% Cost Recovery)",B.akI)
B.ap6=s(["Harassment, abusive language, loud arguments, or disrespectful behavior towards staff or fellow members will not be tolerated.","Recording unauthorized photos or videos of other gym members without their consent is strictly prohibited.","Gym management reserves the right to immediately terminate the membership of any individual violating decorum without refund."],t.s)
B.a6X=new A.f1("conduct",B.jj,"Decorum, Discipline & Zero Tolerance Policy",B.ap6)
B.ap0=s([B.a74,B.a7c,B.a6Z,B.a6V,B.a7d,B.a73,B.a6X],t.Xh)
